def godot3d_scaffold_files(name: str, slug: str, description: str = "") -> dict[str, str]:
    title = (name or slug or "Godot3D").strip()
    desc = (description or title).strip()[:400]
    mapping = {"__NAME__": title, "__SLUG__": slug or "godot-3d", "__DESC__": desc}
    raw = {
        "project.godot": _PROJECT,
        "scenes/main.tscn": _MAIN_TSCN,
        "scripts/player.gd": _PLAYER_GD,
        "scripts/plate.gd": _PLATE_GD,
        "scripts/hud.gd": _HUD_GD,
        "scripts/autoload/game.gd": _GAME_GD,
        "scripts/autoload/probe.gd": _PROBE_GD,
        "icon.svg": _ICON_SVG,
        "studio/preview/index.html": _PREVIEW_HTML,
        "README.md": _README,
        ".gitignore": _GITIGNORE,
    }
    out: dict[str, str] = {}
    for rel, content in raw.items():
        text = content
        for k, v in mapping.items():
            text = text.replace(k, v)
        out[rel] = text
    return out


def write_godot3d_scaffold(pdir: Path, name: str, slug: str, description: str = "") -> list[str]:
    pdir = Path(pdir)
    pdir.mkdir(parents=True, exist_ok=True)
    written: list[str] = []
    for rel, content in godot3d_scaffold_files(name, slug, description).items():
        target = pdir / rel
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
        written.append(rel)
    write_asset_contract(pdir, name="greybox_proxy")
    if "studio/asset_contract.json" not in written:
        written.append("studio/asset_contract.json")
    write_scene_index(pdir)
    if "studio/scene_index.json" not in written:
        written.append("studio/scene_index.json")
    dod_path = pdir / "studio" / "dod.json"
    from .godot_dod import dod_v2_static
    dod_path.write_text(json.dumps(dod_v2_static(pdir), indent=2) + "\n", encoding="utf-8")
    if "studio/dod.json" not in written:
        written.append("studio/dod.json")
    if written:
        log.info("godot 3d scaffold: %s → %s", slug, written)
    return written
